INSERT INTO capaian_pembelajaran (id, mapel_id, fase, jenjang, deskripsi) VALUES
  ('66666666-0001-0001-0001-666666666666', '55555555-0001-0001-0001-555555555555', 'B', 'MI', 'Peserta didik dapat menyelesaikan masalah yang berkaitan dengan operasi hitung bilangan cacah, pecahan sederhana, pengukuran, dan geometri dasar.'),
  ('66666666-0002-0002-0002-666666666666', '55555555-0002-0002-0002-555555555555', 'B', 'MI', 'Peserta didik dapat memahami, mengolah, dan menyajikan informasi dari teks narasi, deskripsi, dan instruksi dalam bahasa Indonesia.'),
  ('66666666-0003-0003-0003-666666666666', '55555555-0003-0003-0003-555555555555', 'B', 'MI', 'Peserta didik dapat membaca, menghafal, dan memahami kandungan ayat-ayat Al-Quran dan Hadis pilihan yang berkaitan dengan akhlak mulia.');
INSERT INTO tujuan_pembelajaran (id, cp_id, kode, deskripsi, urutan) VALUES
  ('77777777-0001-0001-0001-777777777777', '66666666-0001-0001-0001-666666666666', 'MTK.B.1', 'Menyelesaikan operasi penjumlahan dan pengurangan bilangan cacah sampai 10.000', 1),
  ('77777777-0002-0002-0002-777777777777', '66666666-0001-0001-0001-666666666666', 'MTK.B.2', 'Menyelesaikan operasi perkalian dan pembagian bilangan cacah', 2),
  ('77777777-0003-0003-0003-777777777777', '66666666-0001-0001-0001-666666666666', 'MTK.B.3', 'Mengenal dan menentukan pecahan sederhana', 3),
  ('77777777-0004-0004-0004-777777777777', '66666666-0001-0001-0001-666666666666', 'MTK.B.4', 'Mengukur panjang, berat, dan waktu menggunakan satuan baku', 4);
INSERT INTO tujuan_pembelajaran (id, cp_id, kode, deskripsi, urutan) VALUES
  ('77777777-0005-0005-0005-777777777777', '66666666-0002-0002-0002-666666666666', 'BI.B.1', 'Membaca dan memahami isi teks narasi dengan lancar', 1),
  ('77777777-0006-0006-0006-777777777777', '66666666-0002-0002-0002-666666666666', 'BI.B.2', 'Menulis paragraf deskripsi dengan kalimat yang runtut dan padu', 2),
  ('77777777-0007-0007-0007-777777777777', '66666666-0002-0002-0002-666666666666', 'BI.B.3', 'Menyampaikan informasi secara lisan dengan percaya diri', 3);
INSERT INTO tujuan_pembelajaran (id, cp_id, kode, deskripsi, urutan) VALUES
  ('77777777-0008-0008-0008-777777777777', '66666666-0003-0003-0003-666666666666', 'QH.B.1', 'Membaca surah-surah pendek dengan tajwid yang benar', 1),
  ('77777777-0009-0009-0009-777777777777', '66666666-0003-0003-0003-666666666666', 'QH.B.2', 'Menghafal surah Al-Fatihah sampai An-Nas dengan lancar', 2),
